! ============================================================
! VML 线程扩展库 — Fortran
!
! 使用示例:
!   call asm("SYSCALL 300")   ! 创建线程
!   call asm("SYSCALL 301")   ! 退出线程
!   call asm("SYSCALL 302")   ! 等待线程结束
!   call asm("SYSCALL 303")   ! 让出 CPU 时间片
!
! 注意: 仅在 OS 模式 (--mode os) 下可用
! ============================================================

! ============================================================
! SYSCALL 300 — ThreadCreate
! 创建新线程
! 参数:
!   R0 = 线程入口函数地址
!   R1 = 栈大小 (字节, 最小 1024)
! 返回: R0 = 线程 ID (>0 成功), <0 错误
!
! Fortran 使用示例:
!   ! 创建线程，入口函数地址在 R0，栈大小 4096 字节
!   ! R0 = 函数地址, R1 = 4096
!   call asm("SYSCALL 300")
!   ! 返回: R0 = 线程 ID
! ============================================================

! ============================================================
! SYSCALL 301 — ThreadExit
! 终止当前线程
! 参数: 无
! 返回值: 无
!
! Fortran 使用示例:
!   call asm("SYSCALL 301")
! ============================================================

! ============================================================
! SYSCALL 302 — ThreadJoin
! 等待指定线程结束
! 参数: R0 = 线程 ID
! 返回: R0 = 0 成功, <0 错误
!
! 注意: 当前为 stub, 返回 NOT_SUPPORTED
!
! Fortran 使用示例:
!   ! 等待线程 thread_id 结束
!   ! R0 = thread_id
!   call asm("SYSCALL 302")
! ============================================================

! ============================================================
! SYSCALL 303 — ThreadYield
! 让出 CPU 时间片
! 参数: 无
! 返回: R0 = 0
!
! Fortran 使用示例:
!   call asm("SYSCALL 303")
! ============================================================

! ============================================================
! 使用模式示例（概念性代码）:
!
! program thread_example
!   implicit none
!   ! 1. 创建线程
!   call asm("SYSCALL 300")
!   !   R0 包含线程 ID
!
!   ! 2. 主线程继续执行
!   call asm("SYSCALL 52")     ! Sleep 1000ms
!
!   ! 3. 等待子线程结束
!   call asm("SYSCALL 302")    ! ThreadJoin
! end program thread_example
!
! 注意:
! - 线程同步需要互斥锁 (SYSCALL 310-312) 和条件变量 (313-316)
! - 参见 mutex.f90 和 cond.f90
! ============================================================
